<script setup>
import {onMounted,ref,reactive} from 'vue'
import {api,errorMessage,localTime,filterParams} from './api'
defineProps({people:{type:Array,default:()=>[]}})
const filters=reactive({user_id:'',from:'',to:''}),rows=ref([]),page=ref(1),last=ref(1),busy=ref(false),error=ref('')
async function load(reset=false){if(reset)page.value=1;busy.value=true;error.value='';try{const {data}=await api.get('/api/admin/deletions',{params:{...filterParams(filters),page:page.value}});rows.value=data.data;last.value=data.last_page}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template><section><p class="notice">Neutral deletion: no anomaly flags or score penalties. Dates below are displayed in your local timezone; filters use UTC.</p><form class="filter-bar" @submit.prevent="load(true)"><label>Employee<select v-model="filters.user_id"><option value="">All employees</option><option v-for="p in people" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>From (UTC)<input v-model="filters.from" type="date"></label><label>Through (UTC)<input v-model="filters.to" type="date" :min="filters.from"></label><button :disabled="busy">Apply</button></form><p v-if="error" class="notice danger">{{error}}</p><div class="card table-scroll"><table><thead><tr><th>Employee</th><th>Deleted</th><th>Capture / device</th><th>Reason</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.employee_name}}</td><td>{{localTime(r.deleted_at)}}</td><td class="wrap">{{r.capture_type}} · {{r.capture_id}}<small>{{r.device_id}}</small></td><td class="wrap">{{r.reason || 'Not provided'}}</td></tr></tbody></table><p v-if="!rows.length">{{busy?'Loading…':'No deletion events in this view.'}}</p></div><div class="pagination"><span>Page {{page}} of {{last}}</span><button :disabled="busy||page<=1" @click="page--;load()">Previous</button><button :disabled="busy||page>=last" @click="page++;load()">Next</button></div></section></template>
